// Loon response body filtering script backed by Rust WASM
// Target: /parenting/pt/homepage/get/v2
(() => {
  const WASM_BASE64 = "";
  const OPERATION = 1;
  let wasmPromise;

  const utf8Encode = (text) => {
    const bytes = [];
    for (let index = 0; index < text.length; index++) {
      let code = text.charCodeAt(index);
      if (code >= 0xd800 && code <= 0xdbff && index + 1 < text.length) {
        const next = text.charCodeAt(index + 1);
        if (next >= 0xdc00 && next <= 0xdfff) {
          code = 0x10000 + ((code - 0xd800) << 10) + next - 0xdc00;
          index++;
        }
      }
      if (code < 0x80) bytes.push(code);
      else if (code < 0x800) bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
      else if (code < 0x10000) bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
      else bytes.push(0xf0 | (code >> 18), 0x80 | ((code >> 12) & 0x3f), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    }
    return new Uint8Array(bytes);
  };

  const utf8Decode = (bytes) => {
    let text = "";
    for (let index = 0; index < bytes.length;) {
      const first = bytes[index++];
      if (first < 0x80) text += String.fromCharCode(first);
      else if ((first & 0xe0) === 0xc0) text += String.fromCharCode(((first & 0x1f) << 6) | (bytes[index++] & 0x3f));
      else if ((first & 0xf0) === 0xe0) text += String.fromCharCode(((first & 0x0f) << 12) | ((bytes[index++] & 0x3f) << 6) | (bytes[index++] & 0x3f));
      else {
        const code = ((first & 0x07) << 18) | ((bytes[index++] & 0x3f) << 12) | ((bytes[index++] & 0x3f) << 6) | (bytes[index++] & 0x3f);
        const pair = code - 0x10000;
        text += String.fromCharCode(0xd800 | (pair >> 10), 0xdc00 | (pair & 0x3ff));
      }
    }
    return text;
  };

  const responseHeader = (name) => {
    const headers = $response.headers || {};
    const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === name.toLowerCase());
    return key ? String(headers[key]) : "";
  };

  const requestToken = () => {
    const match = String($request.url).match(/[?&]token=([^&]+)/);
    return match ? decodeURIComponent(match[1]) : "";
  };

  const getWasm = () => {
    if (!wasmPromise) {
      const binary = atob(WASM_BASE64);
      const bytes = new Uint8Array(binary.length);
      for (let index = 0; index < binary.length; index++) bytes[index] = binary.charCodeAt(index);
      wasmPromise = WebAssembly.instantiate(bytes).then((result) => result.instance.exports);
    }
    return wasmPromise;
  };

  const callWasm = async (context) => {
    const wasm = await getWasm();
    const input = utf8Encode(JSON.stringify(context));
    const pointer = wasm.alloc(input.length);
    try {
      new Uint8Array(wasm.memory.buffer, pointer, input.length).set(input);
      const outputPointer = wasm.process(pointer, input.length);
      const outputLength = wasm.output_len();
      return utf8Decode(new Uint8Array(wasm.memory.buffer, outputPointer, outputLength));
    } finally {
      wasm.dealloc(pointer, input.length);
    }
  };

  if (!$loon || !$request || !$response || !$response.body) return $done({});
  Promise.resolve()
    .then(() => callWasm({
      version: 1,
      operation: OPERATION,
      body: String($response.body),
      token: requestToken(),
      encrypted: responseHeader("enctype") === "1",
      gzip: responseHeader("qbbgzip") === "1",
    }))
    .then((body) => $done(body === String($response.body) ? {} : { body }))
    .catch(() => $done({}));
})();
